  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is agricultural robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of field, greenhouse, orchard, and packhouse data that trains robots to weed, harvest, scout, and handle produce, using ground cameras, LiDAR, teleoperated picking demonstrations, and aerial imagery across the growing season."
        }
      },
      {
        "@type": "Question",
        "name": "How many seasons of data does an agricultural robot need?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Most teams need data from every growth stage the robot will work in, across more than one site and variety. A first season can cover this if collection is scheduled by crop stage and includes at least two farms."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect harvesting demonstrations for robot learning?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We run teleoperated picking sessions on your robot or ours, with wrist cameras and force sensing, and tag every episode by ripeness, occlusion, and outcome."
        }
      },
      {
        "@type": "Question",
        "name": "Do you use drones for agricultural data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, for field mapping, stand counts, and weed detection, with multispectral calibration and flight altitudes set by the pixels your model needs on target."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle weak GPS under orchard canopy?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We record GNSS quality alongside LiDAR, camera, and IMU data so localization models can be trained and evaluated in the conditions where satellite positioning degrades."
        }
      },
      {
        "@type": "Question",
        "name": "Which crops have you worked with?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Capture methods apply across row crops, orchards, vineyards, and greenhouses. We scope crop-specific details, such as growth stages and ripeness guides, during the pilot."
        }
      }
    ]
  }
